/// <reference lib="webworker" />
/*
 * TableRounds service worker — Workbox implementation (InjectManifest).
 *
 * Source of truth: this file. The deployable artifact public/sw.js is
 * GENERATED by scripts/build-sw.mjs (esbuild bundle + precache-manifest
 * injection). Never edit public/sw.js by hand.
 *
 * Routing table (registration order matters — first match wins):
 *
 *   1. Precached URLs (workbox-precaching)  … served from precache
 *   2. API mutations POST/PUT/PATCH/DELETE  … NetworkOnly (never cached,
 *      never fabricated — real network errors reach the app untouched)
 *   3. Whitelisted API GETs (dashboard pages) … NetworkFirst + 5 s timeout
 *                                             → tablerounds-api-readonly-v1
 *   4. Fonts (same-origin + gstatic)        … CacheFirst, ~1 year
 *   5. Images (same-origin + _next/image)   … CacheFirst, ~30 days
 *   6. Navigations (mode === 'navigate')    … NetworkFirst + 4 s timeout
 *                                             → offline.html fallback
 *   7. Everything else                      … NOT intercepted; plain network
 *
 * API GET caching is an explicit allowlist (CACHEABLE_API_GET below) mirroring
 * the dashboard routes that must stay usable offline:
 *   /dashboard/user           → /profile, /profile/stats, /profile/connections,
 *                               /profile/discover
 *   /dashboard/user/create-test → /test/question-count
 *   /dashboard/user/previous-test → /test/histories-stats, /test/histories
 *   /dashboard/user/statistics → /statistic
 *   /dashboard/user/leaderboard → /leaderboard, /leaderboard/map-data
 *   /dashboard/user/my-profile → /profile
 *   /dashboard/user/support   → /admin/help
 * Sensitive /auth/*, /admin/user, /subscriptions, /admin/questions and any
 * other endpoint are deliberately NOT cached — only the allowlist is served
 * from cache offline; everything else falls through to the network.
 *
 * NOTE: `navigator.onLine` is never consulted here. It reports interface
 * state, not reachability — strategies react to real request outcomes.
 */

import { clientsClaim, setCacheNameDetails } from 'workbox-core';
import {
  cleanupOutdatedCaches,
  matchPrecache,
  precacheAndRoute,
} from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import {
  CacheFirst,
  NetworkFirst,
  NetworkOnly,
} from 'workbox-strategies';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';
import { ExpirationPlugin } from 'workbox-expiration';
import * as navigationPreload from 'workbox-navigation-preload';

declare const self: ServiceWorkerGlobalScope;

/**
 * Inlined at build time by scripts/build-sw.mjs from NEXT_PUBLIC_API_ENDPOINT.
 * e.g. "https://backend.tablerounds.ai/api" (no trailing slash).
 */
declare const __API_BASE__: string;

// ---------------------------------------------------------------------------
// Cache naming — project-specific, easy to find in DevTools.
// Bump VERSION when a runtime cache's schema/contents change meaningfully;
// Workbox handles precache revisioning on its own.
// ---------------------------------------------------------------------------
const VERSION = 'v1';
const PAGES_CACHE = `tablerounds-runtime-pages-${VERSION}`;
const IMAGES_CACHE = `tablerounds-runtime-images-${VERSION}`;
const FONTS_CACHE = `tablerounds-runtime-fonts-${VERSION}`;
const API_CACHE = `tablerounds-api-readonly-${VERSION}`;
const OFFLINE_URL = '/offline.html';

setCacheNameDetails({ prefix: 'tablerounds' }); // precache: tablerounds-precache-v2-…

precacheAndRoute(self.__WB_MANIFEST);
cleanupOutdatedCaches(); // removes old workbox-precache-* versions
// ---------------------------------------------------------------------------
// API helpers
// ---------------------------------------------------------------------------
let API_ORIGIN = '';
let API_PATH_PREFIX = '';
try {
  const parsed = new URL(__API_BASE__);
  API_ORIGIN = parsed.origin;
  // "/api" when the base is https://host/api — "" for a bare host.
  API_PATH_PREFIX = parsed.pathname.replace(/\/+$/, '');
} catch {
  /* invalid config → all API routes stay disabled, requests pass through */
}

function isApiUrl(url: URL): boolean {
  if (API_ORIGIN && url.origin === API_ORIGIN) {
    return url.pathname.startsWith(API_PATH_PREFIX || '/');
  }
  // Also cover a same-origin /api proxy setup.
  return url.origin === self.location.origin && url.pathname.startsWith('/api/');
}

/** Path relative to the API prefix, e.g. "/test/histories". */
function apiPath(url: URL): string {
  if (url.origin === API_ORIGIN && API_PATH_PREFIX) {
    return url.pathname.slice(API_PATH_PREFIX.length) || '/';
  }
  // Same-origin /api proxy setup.
  return url.pathname.replace(/^\/api/, '') || '/';
}

// ---------------------------------------------------------------------------
// 2. API mutations — NetworkOnly. Registered for all API requests regardless
//    of path: a failed mutation surfaces as a genuine network error to the
//    page (e.g. a quiz submission, payment, profile update) — the service
//    worker NEVER fabricates a response body for a write.
// ---------------------------------------------------------------------------
if (API_ORIGIN) {
  const mutationHandler = new NetworkOnly();
  for (const method of ['POST', 'PUT', 'PATCH', 'DELETE'] as const) {
    registerRoute(({ url }) => isApiUrl(url), mutationHandler, method);
  }
}

// ---------------------------------------------------------------------------
// 3. Whitelisted API GETs — NetworkFirst, only HTTP 200 cached, 7-day TTL.
//    This is the allowlist that keeps the specified dashboard routes readable
//    offline. Matching is on the API-relative pathname (query strings are NOT
//    part of the pattern), so paginated/filtered requests like
//    /test/histories?page=2&limit=10 are cached by their full URL.
// ---------------------------------------------------------------------------
const CACHEABLE_API_GET = new RegExp(
  '^/(?:' +
    'profile(?:/(?:stats|connections|discover))?' +
    '|test/(?:question-count|histories-stats|histories)' +
    '|statistic' +
    '|leaderboard(?:/map-data)?' +
    '|admin/help' +
    ')/?$',
);

registerRoute(
  ({ url }) => isApiUrl(url) && CACHEABLE_API_GET.test(apiPath(url)),
  new NetworkFirst({
    cacheName: API_CACHE,
    networkTimeoutSeconds: 5,
    plugins: [
      new CacheableResponsePlugin({ statuses: [200] }),
      new ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 7 * 24 * 60 * 60,
        purgeOnQuotaError: true,
      }),
    ],
  }),
  'GET',
);

// ---------------------------------------------------------------------------
// 4. Fonts — immutable in practice; long-lived cache.
//    next/font/google self-hosts fonts under /_next/static/media;
//    fonts.gstatic.com covered defensively. Status 0 allowed for opaque
//    cross-origin responses.
// ---------------------------------------------------------------------------
registerRoute(
  ({ url, request }) =>
    request.method === 'GET' &&
    ((url.origin === self.location.origin ||
      url.origin === 'https://fonts.gstatic.com') &&
      /\.(?:woff2?|ttf|otf)$/i.test(url.pathname)),
  new CacheFirst({
    cacheName: FONTS_CACHE,
    plugins: [
      new CacheableResponsePlugin({ statuses: [0, 200] }),
      new ExpirationPlugin({
        maxEntries: 20,
        maxAgeSeconds: 365 * 24 * 60 * 60,
        purgeOnQuotaError: true,
      }),
    ],
  }),
);

// ---------------------------------------------------------------------------
// 5. Same-origin images (incl. /_next/image optimizer output) — CacheFirst
//    with bounded entries and TTL. Remote hosts (backend storage, S3 CDN) are
//    intentionally not cached: the app serves profile photos and progress
//    visuals that we do not want to persist without an explicit policy.
// ---------------------------------------------------------------------------
registerRoute(
  ({ url, request }) =>
    url.origin === self.location.origin &&
    request.method === 'GET' &&
    (/\.(?:png|jpe?g|gif|webp|avif|ico|svg)$/i.test(url.pathname) ||
      url.pathname.startsWith('/_next/image')),
  new CacheFirst({
    cacheName: IMAGES_CACHE,
    plugins: [
      new CacheableResponsePlugin({ statuses: [200] }),
      new ExpirationPlugin({
        maxEntries: 60,
        maxAgeSeconds: 30 * 24 * 60 * 60,
        purgeOnQuotaError: true,
      }),
    ],
  }),
);
// ---------------------------------------------------------------------------
// 6. Navigations — NetworkFirst with navigation preload: the browser starts
//    the document request while the SW boots; workbox-strategies' handler
//    consumes event.preloadResponse automatically. On failure: previously
//    cached page → precached /offline.html. This handler can NEVER answer API
//    requests (mode === 'navigate' only), so there is no offline-JSON trap.
// ---------------------------------------------------------------------------
navigationPreload.enable();

const pagesStrategy = new NetworkFirst({
  cacheName: PAGES_CACHE,
  networkTimeoutSeconds: 4,
  plugins: [
    new CacheableResponsePlugin({ statuses: [200] }),
    new ExpirationPlugin({
      maxEntries: 30,
      maxAgeSeconds: 7 * 24 * 60 * 60,
      purgeOnQuotaError: true,
    }),
  ],
});

async function handleNavigation(options: {
  event: ExtendableEvent;
  request: Request;
}): Promise<Response> {
  const event = options.event as FetchEvent;
  const request = options.request;
  let response: Response | undefined;
  try {
    response = await pagesStrategy.handle({ event, request });
  } catch {
    /* fall through to the offline fallback */
  }
  if (response) return response;

  try {
    const fallback = await matchPrecache(OFFLINE_URL);
    if (fallback) return fallback;
  } catch {
    /* precache unavailable — propagate a network error below */
  }
  return Response.error();
}

registerRoute(({ request }) => request.mode === 'navigate', handleNavigation);

// ---------------------------------------------------------------------------
// Lifecycle & controlled updates
// ---------------------------------------------------------------------------
// Legacy vanilla-SW caches from earlier deployments — removed once, then gone.
const LEGACY_CACHE_RE = /^tablerounds-(shell|assets|api)-v\d+$/;

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => LEGACY_CACHE_RE.test(key))
          .map((key) => caches.delete(key)),
      );
      console.log(`[SW] active (${VERSION})`);
    })(),
  );
});

// Take control of open tabs once an update has been approved by the page.
clientsClaim();

// The page decides WHEN a waiting worker activates — never automatically
// (no unconditional skipWaiting: avoids old-HTML/new-JS hydration mismatches).
self.addEventListener('message', (event) => {
  if ((event.data as { type?: string } | undefined)?.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});